  metaLabel: { color: "#668779", fontSize: 10, letterSpacing: 1.5, fontWeight: "700" },
  metaValue: { color: "#dcece4", marginTop: 4, fontWeight: "600" },
  loading: { flex: 1, minHeight: 330, alignItems: "center", justifyContent: "center", gap: 16 },
  muted: { color: "#829c90" },
  error: { color: "#ffaaa3", textAlign: "center", lineHeight: 20 },
  secondaryButton: { borderColor: "#759b89", borderWidth: 1, borderRadius: 10, paddingHorizontal: 20, paddingVertical: 10 },
  secondaryButtonText: { color: "#c6ded2", fontWeight: "700" },
