import { SessionManager } from "./session";
import type { SessionStore } from "./sessionStore";

function fakeStore(overrides: Partial<SessionStore> = {}): jest.Mocked<SessionStore> {
  return {
    readToken: jest.fn().mockResolvedValue(null),
    saveToken: jest.fn().mockResolvedValue(undefined),
    clearToken: jest.fn().mockResolvedValue(undefined),
    ...overrides,
  } as jest.Mocked<SessionStore>;
}

describe("sesión segura", () => {
  test("AT-11-01-01 persiste únicamente el token y lo mantiene en memoria", async () => {
    const store = fakeStore();
    const manager = new SessionManager(store, jest.fn());
    await manager.establish("token-secreto");
    expect(store.saveToken).toHaveBeenCalledWith("token-secreto");
    expect(manager.currentToken()).toBe("token-secreto");
  });

  test("AT-11-01-02 restaura optimistamente sin consultar la API", async () => {
    const store = fakeStore({ readToken: jest.fn().mockResolvedValue("persistido") });
    const manager = new SessionManager(store, jest.fn());
    await expect(manager.restore()).resolves.toEqual({ token: "persistido", readFailed: false });
    expect(manager.currentToken()).toBe("persistido");
  });

  test("AT-11-01-03 restaura ausencia de token", async () => {
    const manager = new SessionManager(fakeStore(), jest.fn());
    await expect(manager.restore()).resolves.toEqual({ token: null, readFailed: false });
  });

  test("AT-11-01-13 sanea un fallo de lectura sin propagar detalles", async () => {
    const store = fakeStore({ readToken: jest.fn().mockRejectedValue(new Error("detalle sensible")) });
    const manager = new SessionManager(store, jest.fn());
    await expect(manager.restore()).resolves.toEqual({ token: null, readFailed: true });
  });

  test("AT-11-01-05/06/14 serializa borrado y navegación concurrentes", async () => {
    let finish!: () => void;
    const pending = new Promise<void>((resolve) => { finish = resolve; });
    const store = fakeStore({ clearToken: jest.fn(() => pending) });
    const cleared = jest.fn();
    const manager = new SessionManager(store, cleared);
    await manager.establish("token");
    const first = manager.clearSingleton();
    const second = manager.clearSingleton();
    expect(first).toBe(second);
    await Promise.resolve();
    expect(store.clearToken).toHaveBeenCalledTimes(1);
    expect(cleared).toHaveBeenCalledTimes(1);
    expect(manager.currentToken()).toBeNull();
    finish();
    await first;
  });

  test("AT-11-01-06 reintenta un borrado fallido sin restaurar ni navegar otra vez", async () => {
    const store = fakeStore({
      readToken: jest.fn().mockResolvedValue("token-antiguo"),
      clearToken: jest.fn()
        .mockRejectedValueOnce(new Error("Keychain temporalmente inaccesible"))
        .mockResolvedValueOnce(undefined),
    });
    const cleared = jest.fn();
    const manager = new SessionManager(store, cleared);
    await manager.restore();
    await manager.clearSingleton();
    await expect(manager.restore()).resolves.toEqual({ token: null, readFailed: false });
    expect(store.clearToken).toHaveBeenCalledTimes(2);
    expect(cleared).toHaveBeenCalledTimes(1);
    expect(manager.currentToken()).toBeNull();
  });

  test("un 401 tardío no borra un login nuevo mientras SecureStore guarda el token", async () => {
    let stored: string | null = null;
    let allowNewSave!: () => void;
    const newSavePending = new Promise<void>((resolve) => { allowNewSave = resolve; });
    const store = fakeStore({
      saveToken: jest.fn(async (token: string) => {
        if (token === "sesion-B") await newSavePending;
        stored = token;
      }),
      clearToken: jest.fn(async () => { stored = null; }),
    });
    const cleared = jest.fn();
    const manager = new SessionManager(store, cleared);
    await manager.establish("sesion-A");

    const establishNew = manager.establish("sesion-B");
    await Promise.resolve();
    // Even a caller that omits the context captures session A at invocation time.
    const staleClear = manager.clearSingleton(undefined, "expired");
    allowNewSave();
    await Promise.all([establishNew, staleClear]);

    expect(stored).toBe("sesion-B");
    expect(manager.currentToken()).toBe("sesion-B");
    expect(store.clearToken).not.toHaveBeenCalled();
    expect(cleared).not.toHaveBeenCalled();
  });

  test("un login nuevo espera a que termine el borrado de la sesión anterior", async () => {
    let stored: string | null = null;
    let allowClear!: () => void;
    const clearPending = new Promise<void>((resolve) => { allowClear = resolve; });
    const store = fakeStore({
      saveToken: jest.fn(async (token: string) => { stored = token; }),
      clearToken: jest.fn(async () => { await clearPending; stored = null; }),
    });
    const manager = new SessionManager(store, jest.fn());
    await manager.establish("sesion-A");

    const clearOld = manager.clearSingleton("sesion-A", "expired");
    await Promise.resolve();
    const establishNew = manager.establish("sesion-B");
    expect(store.saveToken).toHaveBeenCalledTimes(1);
    allowClear();
    await Promise.all([clearOld, establishNew]);

    expect(stored).toBe("sesion-B");
    expect(manager.currentToken()).toBe("sesion-B");
  });
});

