        issues: [
          { field: "email", message: "El email no tiene un formato válido." },
          { path: ["password"], message: "La contraseña no cumple el esquema." },
        ],
      },
      422,
    ));
    const screen = render(<LoginScreen api={client(login)} onAuthenticated={jest.fn()} />);
    fireEvent.changeText(screen.getByLabelText("Email"), "trader@example.com");
    fireEvent.changeText(screen.getByLabelText("Contraseña"), "secreta");
    fireEvent.press(screen.getByRole("button", { name: "Ingresar" }));

    expect(await screen.findByText("El email no tiene un formato válido.")).toBeTruthy();
    expect(screen.getByText("La contraseña no cumple el esquema.")).toBeTruthy();
  });

  test("AT-11-01-11 no escribe token ni password en logs", async () => {
    const spies = ["log", "warn", "error"].map((method) => jest.spyOn(console, method as "log").mockImplementation(() => undefined));
    const secret = "password-muy-secreta";
    const token = "token-muy-secreto";
    const screen = render(
      <LoginScreen
        api={client(jest.fn().mockResolvedValue({ token, expiresAt: "2030-01-01T00:00:00.000Z" }))}
        onAuthenticated={jest.fn().mockResolvedValue(undefined)}
      />,
    );
    fireEvent.changeText(screen.getByLabelText("Email"), "trader@example.com");
    fireEvent.changeText(screen.getByLabelText("Contraseña"), secret);
    fireEvent.press(screen.getByRole("button", { name: "Ingresar" }));
    await waitFor(() => expect(screen.queryByText("Ingresando…")).toBeNull());
    for (const spy of spies) {
      expect(JSON.stringify(spy.mock.calls)).not.toContain(secret);
      expect(JSON.stringify(spy.mock.calls)).not.toContain(token);
      spy.mockRestore();
    }
  });
});

