#!/usr/bin/env python3
"""UI helpers for the Android emulator (adb + uiautomator)."""
from __future__ import annotations

import json
import os
import re
import subprocess
import sys
import time
import xml.etree.ElementTree as ET

SERIAL = os.environ.get("ANDROID_SERIAL", "emulator-5554")
EVID = os.environ.get("EVID_DIR", "/private/tmp/eval-rubrica-mobile-pre-piloto-2b-p2-20260907-155946/evidencia")


def adb(*args: str, check: bool = True, timeout: int = 30) -> subprocess.CompletedProcess:
    return subprocess.run(
        ["adb", "-s", SERIAL, *args],
        check=check,
        capture_output=True,
        timeout=timeout,
        text=True,
    )


def adb_bytes(*args: str, timeout: int = 30) -> bytes:
    r = subprocess.run(
        ["adb", "-s", SERIAL, *args],
        check=True,
        capture_output=True,
        timeout=timeout,
    )
    return r.stdout


def dump_ui(path: str | None = None) -> str:
    adb("shell", "uiautomator", "dump", "/sdcard/ui.xml", check=False)
    xml = adb("shell", "cat", "/sdcard/ui.xml").stdout
    if path:
        os.makedirs(os.path.dirname(path) or ".", exist_ok=True)
        with open(path, "w") as f:
            f.write(xml)
    return xml


def screenshot(path: str) -> str:
    os.makedirs(os.path.dirname(path) or ".", exist_ok=True)
    data = adb_bytes("exec-out", "screencap", "-p")
    # Some adb versions inject CRLF; keep PNG magic.
    if data[:8] != b"\x89PNG\r\n\x1a\n":
        data = data.replace(b"\r\n", b"\n")
    with open(path, "wb") as f:
        f.write(data)
    return path


def parse_nodes(xml: str) -> list[dict]:
    nodes = []
    try:
        root = ET.fromstring(xml)
    except ET.ParseError:
        return nodes
    for el in root.iter("node"):
        b = el.attrib.get("bounds", "")
        m = re.match(r"\[(\d+),(\d+)\]\[(\d+),(\d+)\]", b)
        if not m:
            continue
        x1, y1, x2, y2 = map(int, m.groups())
        nodes.append(
            {
                "text": el.attrib.get("text", ""),
                "desc": el.attrib.get("content-desc", ""),
                "rid": el.attrib.get("resource-id", ""),
                "cls": el.attrib.get("class", ""),
                "clickable": el.attrib.get("clickable", "false") == "true",
                "enabled": el.attrib.get("enabled", "true") == "true",
                "bounds": (x1, y1, x2, y2),
                "cx": (x1 + x2) // 2,
                "cy": (y1 + y2) // 2,
            }
        )
    return nodes


def visible_texts(xml: str) -> list[str]:
    out = []
    for n in parse_nodes(xml):
        if n["text"]:
            out.append(n["text"])
        if n["desc"] and n["desc"] != n["text"]:
            out.append("desc:" + n["desc"])
    return out


