        elif ch == '"':
            escaped.append('\\"')
        elif ch in "()<>|&;$*`\\":
            escaped.append("\\" + ch)
        elif ch == "@":
            escaped.append("\\@")
        elif ch == "&":
            escaped.append("\\&")
