def hide_keyboard() -> None:
    key("KEYCODE_BACK")
    time.sleep(0.4)


def save_pair(prefix: str, xml: str | None = None) -> tuple[str, str]:
    png = os.path.join(EVID, f"{prefix}.png")
    dump = os.path.join(EVID, f"{prefix}.xml")
    screenshot(png)
    if xml is None:
        xml = dump_ui(dump)
    else:
        with open(dump, "w") as f:
            f.write(xml)
    return png, dump


if __name__ == "__main__":
    cmd = sys.argv[1] if len(sys.argv) > 1 else "dump"
    if cmd == "dump":
        xml = dump_ui()
        for t in visible_texts(xml):
