def visible_texts(xml: str) -> list[str]:
    out = []
    for n in parse_nodes(xml):
        if n["text"]:
            out.append(n["text"])
        if n["desc"] and n["desc"] != n["text"]:
            out.append("desc:" + n["desc"])
    return out


def find(xml: str, *, text: str | None = None, desc: str | None = None, contains: str | None = None, rid: str | None = None):
    for n in parse_nodes(xml):
        if text is not None and n["text"] != text:
            continue
        if desc is not None and n["desc"] != desc:
            continue
        if rid is not None and n["rid"] != rid:
            continue
        if contains is not None and contains not in n["text"] and contains not in n["desc"]:
            continue
        return n
    return None


def tap(x: int, y: int) -> None:
    adb("shell", "input", "tap", str(x), str(y))


def tap_node(n: dict) -> None:
    tap(n["cx"], n["cy"])


def wait_dump(pred, timeout: float = 20.0, interval: float = 0.6, path: str | None = None) -> str:
    deadline = time.time() + timeout
    last = ""
    while time.time() < deadline:
        last = dump_ui(path)
        try:
            if pred(last):
                return last
        except Exception:
            pass
        time.sleep(interval)
    return last


def key(name: str) -> None:
    adb("shell", "input", "keyevent", name)


def type_text(text: str) -> None:
    """Type via `input text`, escaping shell/IME specials."""
    if not text:
        return
    # Break into chunks that `input text` accepts; encode space as %s and escape @.
    escaped = []
    for ch in text:
        if ch == " ":
            escaped.append("%s")
        elif ch == "%":
            escaped.append("%%")
        elif ch == "'":
            escaped.append("\\'")
        elif ch == '"':
            escaped.append('\\"')
        elif ch in "()<>|&;$*`\\":
            escaped.append("\\" + ch)
        elif ch == "@":
            escaped.append("\\@")
        elif ch == "&":
            escaped.append("\\&")
        else:
            escaped.append(ch)
    payload = "".join(escaped)
    # Use sh -c so backslashes reach `input`.
    subprocess.run(
        ["adb", "-s", SERIAL, "shell", "input", "text", payload],
        check=True,
        capture_output=True,
        text=True,
    )


def clear_field() -> None:
    # Move to end and delete many times.
    for _ in range(40):
        key("KEYCODE_DEL")
    for _ in range(4):
        key("KEYCODE_FORWARD_DEL")


def focus_and_type(xml: str, label: str, text: str) -> str:
    """Tap an input near a label (or the input with that accessibility label) and type."""
    n = find(xml, desc=label) or find(xml, text=label)
    if n is None:
        raise RuntimeError(f"no widget for {label!r}")
    # If we matched the label TextView, tap a bit below it (the TextInput).
    if n["cls"].endswith("TextView") and not n["desc"]:
        tap(n["cx"], n["cy"] + 70)
    else:
        tap_node(n)
    time.sleep(0.35)
    clear_field()
    type_text(text)
    time.sleep(0.2)
    return dump_ui()


def hide_keyboard() -> None:
    key("KEYCODE_BACK")
    time.sleep(0.4)


def save_pair(prefix: str, xml: str | None = None) -> tuple[str, str]:
    png = os.path.join(EVID, f"{prefix}.png")
    dump = os.path.join(EVID, f"{prefix}.xml")
    screenshot(png)
    if xml is None:
        xml = dump_ui(dump)
    else:
        with open(dump, "w") as f:
            f.write(xml)
    return png, dump


if __name__ == "__main__":
    cmd = sys.argv[1] if len(sys.argv) > 1 else "dump"
    if cmd == "dump":
        xml = dump_ui()
        for t in visible_texts(xml):
            print(t)
    elif cmd == "shot":
        print(screenshot(sys.argv[2]))
    elif cmd == "tap-text":
        xml = dump_ui()
        n = find(xml, text=sys.argv[2]) or find(xml, desc=sys.argv[2]) or find(xml, contains=sys.argv[2])
        if not n:
            print("NOT FOUND", file=sys.stderr)
            sys.exit(2)
        print(json.dumps(n))
        tap_node(n)
    elif cmd == "texts":
        print("\n".join(visible_texts(dump_ui())))
    else:
        raise SystemExit("unknown cmd")

