def type_keys(text: str) -> None:
    import string as _string

    letters = {c: 29 + i for i, c in enumerate(_string.ascii_lowercase)}
    digits = {str(i): 7 + i for i in range(10)}
    special = {".": 56, "@": 77, "-": 69, "_": 69}
    codes: list[str] = []
    for ch in text:
        if ch in letters:
            codes.append(str(letters[ch]))
        elif ch in digits:
            codes.append(str(digits[ch]))
        elif ch.lower() in letters and ch.isupper():
            # SHIFT does not reliably apply via keyevent; callers should use
            # type_text() for mixed-case strings without '@'.
            codes.append(str(letters[ch.lower()]))
        elif ch in special:
            codes.append(str(special[ch]))
        else:
            raise ValueError(f"unmapped char {ch!r}")
    for i in range(0, len(codes), 16):
        adb("shell", "input", "keyevent", *codes[i : i + 16])


